/* 학습 해설
 * Stop core cpuslocked·한core의logical CPU
 * CPUstop의작업계약·설정별자료구조·대상·지연실행·callerlock·UPpreempt/IRQfallback을원문으로읽습니다.
 * stop_core_cpuslocked는대상 core의어느 CPU번호를받고해당 core의 logicalCPU들만정지시키는인터페이스입니다. 전체 machine과한 physicalcore의 thread집합은다릅니다. cpus_read_lock보호가필요하고실행된 fn들이모두 0이면 0,하나라도 nonzero이면 nonzero반환이라는 doc계약이있습니다.
 * physicalcore1개의 logicalCPU2개와전체 4core예제를구별합니다. cpu번호를 logicalcount나 cpucap번호로혼동하지않습니다.
 */
int stop_core_cpuslocked(unsigned int cpu, cpu_stop_fn_t fn, void *data);

int stop_machine_from_inactive_cpu(cpu_stop_fn_t fn, void *data,
				   const struct cpumask *cpus);
#else	/* CONFIG_SMP || CONFIG_HOTPLUG_CPU */

static __always_inline int stop_machine_cpuslocked(cpu_stop_fn_t fn, void *data,
					  const struct cpumask *cpus)
{
	unsigned long flags;
	int ret;
	local_irq_save(flags);
	ret = fn(data);
	local_irq_restore(flags);
	return ret;
}

static __always_inline int
stop_machine(cpu_stop_fn_t fn, void *data, const struct cpumask *cpus)
{
	return stop_machine_cpuslocked(fn, data, cpus);
}

static __always_inline int
stop_machine_from_inactive_cpu(cpu_stop_fn_t fn, void *data,
			       const struct cpumask *cpus)

